core_reasoning_1:
\textbf{Claim.}
For an $SU(N)$ gauge-field fluctuation satisfying the twisted $T^2$ boundary conditions
\[
a^{(\ell_3,\ell_4)}_\mu(x,x_3+L_3,x_4)=\omega^{-\ell_3}a^{(\ell_3,\ell_4)}_\mu(x,x_3,x_4),\qquad
a^{(\ell_3,\ell_4)}_\mu(x,x_3,x_4+L_4)=\omega^{-\ell_4}a^{(\ell_3,\ell_4)}_\mu(x,x_3,x_4),
\]
with $\omega=e^{2\pi i/N}$ and $(\ell_3,\ell_4)\neq(0,0)$, the allowed two-dimensional masses are
\[
m^2_{N k_3+\ell_3,N k_4+\ell_4}
=
\left(\frac{2\pi}{N}\right)^2
\left(
\frac{(N k_3+\ell_3)^2}{L_3^2}
+
\frac{(N k_4+\ell_4)^2}{L_4^2}
\right),
\]
and no two-dimensional zero mode exists.

\textbf{Premises.}
\begin{align*}
\text{(P1)}\quad &N\ge2,\quad \omega:=e^{2\pi i/N},\quad L_3,L_4>0.\\
\text{(P2)}\quad &k_3,k_4\in\mathbb Z,\quad \ell_3,\ell_4\in\{0,1,\ldots,N-1\},\quad (\ell_3,\ell_4)\neq(0,0).\\
\text{(P3)}\quad &a^{(\ell_3,\ell_4)}_\mu(x,x_3+L_3,x_4)=\omega^{-\ell_3}a^{(\ell_3,\ell_4)}_\mu(x,x_3,x_4).\\
\text{(P4)}\quad &a^{(\ell_3,\ell_4)}_\mu(x,x_3,x_4+L_4)=\omega^{-\ell_4}a^{(\ell_3,\ell_4)}_\mu(x,x_3,x_4).\\
\text{(P5)}\quad &a^{(\ell_3,\ell_4)}_\mu=\widetilde a_\mu(x)\exp[-i(\kappa_3x_3+\kappa_4x_4)].\\
\text{(P6)}\quad &m^2=\kappa_3^2+\kappa_4^2.\\
\text{(P7)}\quad &e^{-i\kappa_jL_j}=e^{-2\pi i\ell_j/N}\Longleftrightarrow
\kappa_jL_j=2\pi(k_j+\ell_j/N),\quad j=3,4.
\end{align*}

\textbf{Derivation.}
\begin{align}
e^{-i\kappa_3L_3}
&=\omega^{-\ell_3}
&&\text{by substituting (P5) into (P3)}\\
&=e^{-2\pi i\ell_3/N}
&&\text{by (P1)}\\
\kappa_3L_3
&=2\pi\left(k_3+\frac{\ell_3}{N}\right)
&&\text{by (P7)}\\
\kappa_3
&=\frac{2\pi}{NL_3}(Nk_3+\ell_3)
&&\text{algebra}.
\end{align}
\begin{align}
e^{-i\kappa_4L_4}
&=\omega^{-\ell_4}
&&\text{by substituting (P5) into (P4)}\\
&=e^{-2\pi i\ell_4/N}
&&\text{by (P1)}\\
\kappa_4L_4
&=2\pi\left(k_4+\frac{\ell_4}{N}\right)
&&\text{by (P7)}\\
\kappa_4
&=\frac{2\pi}{NL_4}(Nk_4+\ell_4)
&&\text{algebra}.
\end{align}
\begin{align}
m^2
&=\kappa_3^2+\kappa_4^2
&&\text{by (P6)}\\
&=
\left(\frac{2\pi}{N}\right)^2
\left(
\frac{(Nk_3+\ell_3)^2}{L_3^2}
+
\frac{(Nk_4+\ell_4)^2}{L_4^2}
\right)
&&\text{substitute the two momenta}.
\end{align}
\begin{align}
m^2=0
&\Longrightarrow Nk_3+\ell_3=0\quad\text{and}\quad Nk_4+\ell_4=0
&&\text{sum of nonnegative squares}\\
&\Longrightarrow \ell_3=\ell_4=0
&&\text{since }\ell_j\in\{0,\ldots,N-1\}\\
&\Longrightarrow \text{contradiction with }(\ell_3,\ell_4)\neq(0,0)
&&\text{by (P2)}.
\end{align}

\textbf{Final Result.}
\[
\boxed{
m^2_{N k_3+\ell_3,N k_4+\ell_4}
=
\left(\frac{2\pi}{N}\right)^2
\left(
\frac{(N k_3+\ell_3)^2}{L_3^2}
+
\frac{(N k_4+\ell_4)^2}{L_4^2}
\right)>0
}
\]
\hfill$\blacksquare$

core_reasoning_2:
\textbf{Claim.}
For the classical holonomies $P_3=S^{-p}$ and $P_4=C^{-1}$ with $\gcd(N,p)=1$, the twisted vacuum is center-symmetric:
\[
\operatorname{tr}(P_3^{n_3}P_4^{n_4})=0
\]
unless both $n_3$ and $n_4$ are multiples of $N$.

\textbf{Premises.}
\begin{align*}
\text{(P1)}\quad &N\ge2,\quad \omega:=e^{2\pi i/N},\quad \gcd(N,p)=1.\\
\text{(P2)}\quad &S^N=C^N=1,\qquad SC=\omega CS.\\
\text{(P3)}\quad &P_3:=S^{-p},\qquad P_4:=C^{-1}.\\
\text{(P4)}\quad &\operatorname{tr}(S^aC^b)=0\text{ unless }a\equiv0\pmod N\text{ and }b\equiv0\pmod N.\\
\text{(P5)}\quad &\gcd(N,p)=1\text{ implies }pn_3\equiv0\pmod N\Longleftrightarrow n_3\equiv0\pmod N.
\end{align*}

\textbf{Derivation.}
\begin{align}
P_3^{n_3}P_4^{n_4}
&=(S^{-p})^{n_3}(C^{-1})^{n_4}
&&\text{by (P3)}\\
&=S^{-pn_3}C^{-n_4}
&&\text{powers of a fixed matrix}.
\end{align}
\begin{align}
\operatorname{tr}(P_3^{n_3}P_4^{n_4})\neq0
&\Longrightarrow -pn_3\equiv0\pmod N\quad\text{and}\quad -n_4\equiv0\pmod N
&&\text{by (P4)}\\
&\Longrightarrow pn_3\equiv0\pmod N\quad\text{and}\quad n_4\equiv0\pmod N
&&\text{multiply congruences by }-1\\
&\Longrightarrow n_3\equiv0\pmod N\quad\text{and}\quad n_4\equiv0\pmod N
&&\text{by (P5)}.
\end{align}
Taking the contrapositive gives
\begin{align}
\bigl(n_3\not\equiv0\pmod N\text{ or }n_4\not\equiv0\pmod N\bigr)
&\Longrightarrow \operatorname{tr}(P_3^{n_3}P_4^{n_4})=0.
\end{align}

\textbf{Final Result.}
\[
\boxed{
\operatorname{tr}(P_3^{n_3}P_4^{n_4})=0
\quad\text{unless}\quad
n_3\equiv n_4\equiv0\pmod N
}
\]
\hfill$\blacksquare$

core_reasoning_3:
\textbf{Claim.}
For $\gcd(N,p)=1$ and $pq\equiv1\pmod N$, the $q$-weight vector
\[
\vec w_n^{(q)}:=\sum_{a=0}^{q-1}\vec\nu_{n+ap}
\]
satisfies the root decomposition
\[
\vec\alpha_n=\vec w_n^{(q)}-P_W^p\vec w_n^{(q)},
\]
where indices are understood modulo $N$.

\textbf{Premises.}
\begin{align*}
\text{(P1)}\quad &N\ge2,\
\quad p,q\in\mathbb Z,
\quad \gcd(N,p)=1,
\quad pq\equiv1\pmod N.\\
\text{(P2)}\quad &\text{There exists }t\in\mathbb Z\text{ such that }pq=1+Nt.\\
\text{(P3)}\quad &\vec\alpha_j:=\vec\nu_j-\vec\nu_{j+1},\quad \text{with cyclic indices modulo }N.\\
\text{(P4)}\quad &P_W^p\vec\nu_j=\vec\nu_{j+p},\quad \text{with cyclic indices modulo }N.\\
\text{(P5)}\quad &\vec w_n^{(q)}:=\sum_{a=0}^{q-1}\vec\nu_{n+ap}.
\end{align*}

\textbf{Derivation.}
\begin{align}
P_W^p\vec w_n^{(q)}
&=P_W^p\sum_{a=0}^{q-1}\vec\nu_{n+ap}
&&\text{by (P5)}\\
&=\sum_{a=0}^{q-1}P_W^p\vec\nu_{n+ap}
&&\text{linearity of }P_W^p\\
&=\sum_{a=0}^{q-1}\vec\nu_{n+(a+1)p}
&&\text{by (P4)}\\
&=\sum_{a=1}^{q}\vec\nu_{n+ap}
&&\text{reindex }a\mapsto a+1.
\end{align}
\begin{align}
\vec w_n^{(q)}-P_W^p\vec w_n^{(q)}
&=\sum_{a=0}^{q-1}\vec\nu_{n+ap}-\sum_{a=1}^{q}\vec\nu_{n+ap}
&&\text{by (P5) and the preceding result}\\
&=\vec\nu_n-\vec\nu_{n+qp}
&&\text{telescopic cancellation}\\
&=\vec\nu_n-\vec\nu_{n+1+Nt}
&&\text{by (P2)}\\
&=\vec\nu_n-\vec\nu_{n+1}
&&\text{cyclic indices modulo }N\\
&=\vec\alpha_n
&&\text{by (P3)}.
\end{align}

\textbf{Final Result.}
\[
\boxed{
\vec\alpha_n=\vec w_n^{(q)}-P_W^p\vec w_n^{(q)},
\qquad
\vec w_n^{(q)}=\sum_{a=0}^{q-1}\vec\nu_{n+ap}
}
\]
\hfill$\blacksquare$

core_reasoning_4:
\textbf{Claim.}
In the asymmetric regime $L_3\gg NL_4$, the KvBLLY-monopole solution with the center-twisted boundary condition approaches the center-symmetric holonomy exponentially as $|x|\to\infty$ and has fractional topological charge $Q_{\rm top}=1/N$.

\textbf{Premises.}
\begin{align*}
\text{(P1)}\quad &L_3,L_4>0,
\quad L_3\gg NL_4,
\quad \vec\varphi_c:=\frac{2\pi}{N}\vec\rho.\\
\text{(P2)}\quad &\vec z(x,x_3)=P_W^{-p}\vec z(x,x_3+L_3)\text{ is the center-twisted boundary condition.}\\
\text{(P3)}\quad &\vec\varphi(x,x_3)-\vec\varphi_c=
\frac{ig^2}{4\pi}\left(\vec\sigma(x,x_3)+\frac{\theta}{2\pi}(\vec\varphi(x,x_3)-\vec\varphi_c)\right).\\
\text{(P4)}\quad &\vec\varphi(x,x_3)-\vec\varphi_c
=-\frac{L_4}{2}\sum_{k\in\mathbb Z}\vec w_{n+pk}^{(q)}
\left(
\frac{1}{|(x,x_3-x_{3,*}-kL_3)|}
-
\frac{1}{|(x,x_3-x_{3,*}-(k-1)L_3)|}
\right).\\
\text{(P5)}\quad &\text{The Fourier form of (P4) contains only modes }K_0\left(\frac{2\pi m|x|}{NL_3}\right)\text{ with }m\ge1.\\
\text{(P6)}\quad &K_0(y)=O(e^{-y})\text{ as }y\to\infty.\\
\text{(P7)}\quad &Q_{\rm top}=\frac{1}{N}+\frac{1}{2\pi}\vec\alpha_n\cdot(\vec\varphi_\infty-\vec\varphi_c).\\
\text{(P8)}\quad &\vec\varphi_\infty:=\lim_{|x|\to\infty}\vec\varphi(x,x_3).
\end{align*}

\textbf{Derivation.}
\begin{align}
\vec\varphi(x,x_3)-\vec\varphi_c
&=O\left(e^{-2\pi |x|/(NL_3)}\right)
&&\text{by (P5), (P6), and the smallest mode }m=1.
\end{align}
\begin{align}
\lim_{|x|\to\infty}\left(\vec\varphi(x,x_3)-\vec\varphi_c\right)
&=0
&&\text{because }e^{-2\pi |x|/(NL_3)}\to0\\
\vec\varphi_\infty
&=\vec\varphi_c
&&\text{by (P8)}.
\end{align}
\begin{align}
Q_{\rm top}
&=\frac{1}{N}+\frac{1}{2\pi}\vec\alpha_n\cdot(\vec\varphi_\infty-\vec\varphi_c)
&&\text{by (P7)}\\
&=\frac{1}{N}+\frac{1}{2\pi}\vec\alpha_n\cdot(\vec\varphi_c-\vec\varphi_c)
&&\text{substitute }\vec\varphi_\infty=\vec\varphi_c\\
&=\frac{1}{N}
&&\text{zero vector has zero inner product}.
\end{align}
The same exponential falloff applies to $\vec\sigma$ because (P3) linearly relates $\vec\sigma$ to $\vec\varphi-\vec\varphi_c$.

\textbf{Final Result.}
\[
\boxed{
\vec\sigma,\ \vec\varphi-\vec\varphi_c=O\left(e^{-2\pi |x|/(NL_3)}\right),
\qquad
Q_{\rm top}=\frac{1}{N}
}
\]
\hfill$\blacksquare$

core_reasoning_5:
\textbf{Claim.}
A center vortex carrying magnetic flux $-2\pi\vec w_n^{(q)}$ multiplies the fundamental Wilson loop by the center phase
\[
W(C)\mapsto e^{2\pi iq/N}W(C).
\]

\textbf{Premises.}
\begin{align*}
\text{(P1)}\quad &\vec w_n^{(q)}:=\sum_{a=0}^{q-1}\vec\nu_{n+ap},\quad \text{with }q\text{ distinct defining weights modulo }N.\\
\text{(P2)}\quad &\vec\nu_j\cdot\vec\nu_m=\delta_{jm}-\frac{1}{N}.\\
\text{(P3)}\quad &\int_C\vec a=-2\pi\vec w_n^{(q)}\quad\text{when the vortex lies inside }C.\\
\text{(P4)}\quad &W(C):=\frac{1}{N}\sum_{j=1}^{N}\exp\left(i\vec\nu_j\cdot\int_C\vec a\right).\\
\text{(P5)}\quad &e^{-2\pi i}=1.
\end{align*}

\textbf{Derivation.}
Let $S_q:=\{n,n+p,\ldots,n+(q-1)p\}$ be the set of indices appearing in $\vec w_n^{(q)}$.
For $j\in S_q$,
\begin{align}
\vec\nu_j\cdot\vec w_n^{(q)}
&=\sum_{m\in S_q}\vec\nu_j\cdot\vec\nu_m
&&\text{by (P1)}\\
&=\sum_{m\in S_q}\left(\delta_{jm}-\frac{1}{N}\right)
&&\text{by (P2)}\\
&=1-\frac{q}{N}
&&\text{one Kronecker term equals }1\text{ and }|S_q|=q.
\end{align}
For $j\notin S_q$,
\begin{align}
\vec\nu_j\cdot\vec w_n^{(q)}
&=\sum_{m\in S_q}\left(\delta_{jm}-\frac{1}{N}\right)
&&\text{by (P1) and (P2)}\\
&=-\frac{q}{N}
&&\text{all Kronecker terms vanish and }|S_q|=q.
\end{align}
For both cases, the phase is the same:
\begin{align}
\exp\left(i\vec\nu_j\cdot\int_C\vec a\right)
&=\exp\left(-2\pi i\vec\nu_j\cdot\vec w_n^{(q)}\right)
&&\text{by (P3)}.
\end{align}
If $j\in S_q$, then
\begin{align}
\exp\left(-2\pi i\vec\nu_j\cdot\vec w_n^{(q)}\right)
&=\exp\left(-2\pi i\left(1-\frac{q}{N}\right)\right)
&&\text{use the }j\in S_q\text{ dot product}\\
&=e^{2\pi iq/N}
&&\text{by (P5)}.
\end{align}
If $j\notin S_q$, then
\begin{align}
\exp\left(-2\pi i\vec\nu_j\cdot\vec w_n^{(q)}\right)
&=\exp\left(-2\pi i\left(-\frac{q}{N}\right)\right)
&&\text{use the }j\notin S_q\text{ dot product}\\
&=e^{2\pi iq/N}.
\end{align}
Therefore
\begin{align}
W(C)
&=\frac{1}{N}\sum_{j=1}^{N}e^{2\pi iq/N}
&&\text{by (P4) and the case analysis}\\
&=e^{2\pi iq/N}
&&\text{sum }N\text{ identical terms and divide by }N.
\end{align}

\textbf{Final Result.}
\[
\boxed{
W(C)\mapsto e^{2\pi iq/N}W(C)
}
\]
\hfill$\blacksquare$

core_reasoning_6:
\textbf{Claim.}
For $\gcd(N,p)=1$ and $pq\equiv1\pmod N$, a self-dual center vortex with Wilson-loop phase $e^{2\pi iq/N}$ has fractional topological charge $Q_{\rm top}=1/N$ and classical action $S_{\rm YM}=8\pi^2/(Ng^2)$.

\textbf{Premises.}
\begin{align*}
\text{(P1)}\quad &N\ge2,
\quad p,q\in\mathbb Z,
\quad pq\equiv1\pmod N.\\
\text{(P2)}\quad &pq\equiv1\pmod N\Longleftrightarrow \exists t\in\mathbb Z\text{ such that }pq=1+Nt.\\
\text{(P3)}\quad &\text{The center vortex is isolated by compactifying }\mathbb R^2\text{ with flux }-q.\\
\text{(P4)}\quad &\text{For fluxes }(-q,p)\text{ on the two }T^2\text{ factors, }Q_{\rm top}\in pq/N+\mathbb Z.\\
\text{(P5)}\quad &S_{\rm YM}\ge\frac{8\pi^2}{g^2}|Q_{\rm top}|.\\
\text{(P6)}\quad &\text{The minimal center vortex is self-dual, has positive orientation, and saturates (P5).}
\end{align*}

\textbf{Derivation.}
\begin{align}
pq
&=1+Nt
&&\text{by (P1) and (P2)}\\
\frac{pq}{N}
&=\frac{1}{N}+t
&&\text{divide by }N\\
\frac{pq}{N}+\mathbb Z
&=\frac{1}{N}+\mathbb Z
&&\text{because }t\in\mathbb Z.
\end{align}
\begin{align}
Q_{\rm top}
&\in\frac{pq}{N}+\mathbb Z
&&\text{by (P4)}\\
&=\frac{1}{N}+\mathbb Z
&&\text{by the preceding equality}\\
Q_{\rm top}^{\rm min}
&=\frac{1}{N}
&&\text{least positive representative by (P6)}.
\end{align}
\begin{align}
S_{\rm YM}
&=\frac{8\pi^2}{g^2}|Q_{\rm top}^{\rm min}|
&&\text{by saturation in (P6)}\\
&=\frac{8\pi^2}{g^2}\frac{1}{N}
&&\text{substitute }Q_{\rm top}^{\rm min}=1/N\\
&=\frac{8\pi^2}{Ng^2}
&&\text{algebra}.
\end{align}

\textbf{Final Result.}
\[
\boxed{
Q_{\rm top}=\frac{1}{N},
\qquad
S_{\rm YM}=\frac{8\pi^2}{Ng^2}
}
\]
\hfill$\blacksquare$

core_reasoning_7:
\textbf{Claim.}
In the dilute gas of center vortices and anti-vortices on $M_2\times (T^2)_{p/N\,\mathrm{flux}}$, with $V:=\operatorname{Vol}(M_2)$ and normalized away $\theta$-independent constants, the effective partition function has $N$ branches,
\[
Z_{\mathrm{eff},\theta}
=
\sum_{k=0}^{N-1}e^{-VE_k(\theta)},
\qquad
E_k(\theta)=-2K e^{-8\pi^2/(Ng^2)}\cos\left(\frac{\theta-2\pi k}{N}\right).
\]

\textbf{Premises.}
\begin{align*}
\text{(P1)}\quad &n,\bar n\in\mathbb Z_{\ge0}\text{ count vortices and anti-vortices.}\\
\text{(P2)}\quad &\text{A vortex has weight }VK\exp\left[-\frac{8\pi^2}{Ng^2}+\frac{i\theta}{N}\right].\\
\text{(P3)}\quad &\text{An anti-vortex has weight }VK\exp\left[-\frac{8\pi^2}{Ng^2}-\frac{i\theta}{N}\right].\\
\text{(P4)}\quad &Q_{\rm top}=(n-\bar n)/N\text{ and periodic }M_2\text{ requires }n-\bar n\in N\mathbb Z.\\
\text{(P5)}\quad &\Delta_N(r):=\sum_{k=0}^{N-1}e^{-2\pi ikr/N}\text{ vanishes unless }r\in N\mathbb Z.\\
\text{(P6)}\quad &\text{The nonzero value of }\Delta_N(r)\text{ is a }\theta\text{-independent normalization divided out of }Z_{\mathrm{eff},\theta}.\\
\text{(P7)}\quad &\sum_{n=0}^{\infty}\frac{x^n}{n!}=e^x,
\qquad e^{ix}+e^{-ix}=2\cos x.\\
\text{(P8)}\quad &Z_{\mathrm{eff},\theta}=\sum_{k=0}^{N-1}e^{-VE_k(\theta)}\text{ defines }E_k(\theta).
\end{align*}

\textbf{Derivation.}
\begin{align}
Z_{\mathrm{eff},\theta}
&=
\sum_{n,\bar n\ge0}
\frac{\Delta_N(n-\bar n)}{n!\bar n!}
\left(VK e^{-8\pi^2/(Ng^2)+i\theta/N}\right)^n
\left(VK e^{-8\pi^2/(Ng^2)-i\theta/N}\right)^{\bar n}
&&\text{by (P1)--(P6)}\\
&=
\sum_{k=0}^{N-1}
\sum_{n,\bar n\ge0}
\frac{\left(VK e^{-8\pi^2/(Ng^2)}e^{i(\theta-2\pi k)/N}\right)^n}{n!}
\frac{\left(VK e^{-8\pi^2/(Ng^2)}e^{-i(\theta-2\pi k)/N}\right)^{\bar n}}{\bar n!}
&&\text{insert (P5) and collect phases}\\
&=
\sum_{k=0}^{N-1}
\exp\left[VK e^{-8\pi^2/(Ng^2)}e^{i(\theta-2\pi k)/N}\right]
\exp\left[VK e^{-8\pi^2/(Ng^2)}e^{-i(\theta-2\pi k)/N}\right]
&&\text{by (P7)}\\
&=
\sum_{k=0}^{N-1}
\exp\left[2VK e^{-8\pi^2/(Ng^2)}\cos\left(\frac{\theta-2\pi k}{N}\right)\right]
&&\text{by (P7)}.
\end{align}
\begin{align}
e^{-VE_k(\theta)}
&=
\exp\left[2VK e^{-8\pi^2/(Ng^2)}\cos\left(\frac{\theta-2\pi k}{N}\right)\right]
&&\text{compare with (P8)}\\
E_k(\theta)
&=-2K e^{-8\pi^2/(Ng^2)}\cos\left(\frac{\theta-2\pi k}{N}\right)
&&\text{take logarithms and divide by }-V.
\end{align}

\textbf{Final Result.}
\[
\boxed{
Z_{\mathrm{eff},\theta}=\sum_{k=0}^{N-1}e^{-VE_k(\theta)},
\qquad
E_k(\theta)=-2K e^{-8\pi^2/(Ng^2)}\cos\left(\frac{\theta-2\pi k}{N}\right)
}
\]
\hfill$\blacksquare$

core_reasoning_9:
