core_reasoning_10:
\textbf{Claim.}
If $\int_{M_2}B_{2d}=m$ and $A_3=A_4=0$, the background field imposes
\[
n-\bar n\equiv -pm\pmod N,
\]
which simultaneously gives the shifted topological charge
\[
Q_{\rm top}\in-\frac{pm}{N}+\mathbb Z
\]
and cancels the fractional magnetic flux modulo one:
\[
\frac{q}{N}(n-\bar n)+\frac{m}{N}=0\pmod1.
\]

\textbf{Premises.}
\begin{align*}
\text{(P1)}\quad &N\ge2,
\quad pq\equiv1\pmod N,
\quad m:=\int_{M_2}B_{2d}\in\mathbb Z,
\quad A_3=A_4=0.\\
\text{(P2)}\quad &\text{The background-dependent branch factor is }e^{-2\pi ikpm/N}.\\
\text{(P3)}\quad &\text{The Fourier constraint from the vortex sum is }
\sum_{k=0}^{N-1}e^{-2\pi ik(n-\bar n+pm)/N}.\\
\text{(P4)}\quad &\sum_{k=0}^{N-1}e^{-2\pi ikr/N}\neq0\Longleftrightarrow r\equiv0\pmod N.\\
\text{(P5)}\quad &Q_{\rm top}=(n-\bar n)/N.\\
\text{(P6)}\quad &\text{Each center vortex carries magnetic flux }q/N\text{, and }B_{2d}\text{ contributes }m/N.
\end{align*}

\textbf{Derivation.}
\begin{align}
\sum_{k=0}^{N-1}e^{-2\pi ik(n-\bar n+pm)/N}\neq0
&\Longleftrightarrow n-\bar n+pm\equiv0\pmod N
&&\text{by (P3) and (P4)}\\
&\Longleftrightarrow n-\bar n\equiv -pm\pmod N
&&\text{subtract }pm.
\end{align}
Thus there exists $s\in\mathbb Z$ such that
\begin{align}
n-\bar n&=-pm+Ns.
\end{align}
Then
\begin{align}
Q_{\rm top}
&=\frac{n-\bar n}{N}
&&\text{by (P5)}\\
&=\frac{-pm+Ns}{N}
&&\text{substitute }n-\bar n=-pm+Ns\\
&=-\frac{pm}{N}+s
&&\text{algebra}\\
&\in-\frac{pm}{N}+\mathbb Z
&&\text{since }s\in\mathbb Z.
\end{align}
The total fractional magnetic flux is
\begin{align}
\frac{q}{N}(n-\bar n)+\frac{m}{N}
&\equiv \frac{q}{N}(-pm)+\frac{m}{N}
&&\text{use }n-\bar n\equiv -pm\pmod N\\
&=\frac{m(1-qp)}{N}
&&\text{algebra}\\
&\equiv0\pmod1
&&\text{because }qp\equiv1\pmod N.
\end{align}

\textbf{Final Result.}
\[
\boxed{
n-\bar n\equiv -pm\pmod N,
\qquad
Q_{\rm top}\in-\frac{pm}{N}+\mathbb Z,
\qquad
\frac{q}{N}(n-\bar n)+\frac{m}{N}=0\pmod1
}
\]
\hfill$\blacksquare$

core_reasoning_12:
\textbf{Claim.}
In the one-site $T^2$ approximation, the action-versus-entropy estimate predicts a weak-coupling transition at
\[
\lambda_*=O(N^{-2})
\]
for fixed $p=O(1)$, because the singular-toron action cost is $O(\lambda^{-1})$ while its entropy gain is $O(N^2)$.

\textbf{Premises.}
\begin{align*}
\text{(P1)}\quad &\lambda:=Ng^2,
\quad p=O(1),
\quad N\to\infty.\\
\text{(P2)}\quad &\text{The twist-eater vacuum has }V_{\rm eff}^{\rm twist}=0.\\
\text{(P3)}\quad &\text{For a singular toron, }V_{\rm cl}^{\rm toron}=\frac{4N^2}{\lambda}\sin^2\left(\frac{\pi p}{N}\right).\\
\text{(P4)}\quad &\text{The singular-toron entropy contribution is }-cN^2\text{ with }c=O(1),\ c>0.\\
\text{(P5)}\quad &V_{\rm eff}^{\rm toron}=V_{\rm cl}^{\rm toron}-cN^2.\\
\text{(P6)}\quad &\sin x=x+O(x^3)\text{ as }x\to0.\\
\text{(P7)}\quad &\lambda_*\text{ is estimated by }V_{\rm eff}^{\rm toron}=V_{\rm eff}^{\rm twist}.
\end{align*}

\textbf{Derivation.}
\begin{align}
\sin\left(\frac{\pi p}{N}\right)
&=\frac{\pi p}{N}+O(N^{-3})
&&\text{by (P1) and (P6)}\\
\sin^2\left(\frac{\pi p}{N}\right)
&=\frac{\pi^2p^2}{N^2}+O(N^{-4})
&&\text{square the preceding expansion}.
\end{align}
\begin{align}
V_{\rm cl}^{\rm toron}
&=\frac{4N^2}{\lambda}\sin^2\left(\frac{\pi p}{N}\right)
&&\text{by (P3)}\\
&=\frac{4N^2}{\lambda}\left(\frac{\pi^2p^2}{N^2}+O(N^{-4})\right)
&&\text{substitute the expansion}\\
&=\frac{4\pi^2p^2}{\lambda}+O\left(\frac{1}{\lambda N^2}\right)
&&\text{algebra}\\
&=O(\lambda^{-1})
&&\text{since }p=O(1).
\end{align}
Thus
\begin{align}
V_{\rm eff}^{\rm toron}
&=O(\lambda^{-1})-cN^2
&&\text{by (P4) and (P5)}.
\end{align}
At the estimated transition,
\begin{align}
0
&=V_{\rm eff}^{\rm twist}
&&\text{by (P2)}\\
&=V_{\rm eff}^{\rm toron}
&&\text{by (P7)}\\
&=O(\lambda_*^{-1})-cN^2
&&\text{substitute the preceding estimate},
\end{align}
so
\begin{align}
O(\lambda_*^{-1})&=O(N^2)
&&\text{because }c=O(1),\\
\lambda_*&=O(N^{-2})
&&\text{invert the scaling relation}.
\end{align}

\textbf{Final Result.}
\[
\boxed{
V_{\rm cl}^{\rm toron}=O(\lambda^{-1}),
\qquad
\lambda_*=O(N^{-2})
\quad(p=O(1))
}
\]
\hfill$\blacksquare$
